/bin/bash -lc 'set -eu
scratch=$(mktemp -d "$PWD/.desk-review.XXXXXX")
trap '"'python3 -c \"import shutil, sys; shutil.rmtree(sys.argv[1])\" \""'$scratch"'"' EXIT
cp -R release/. \""'$scratch/"
export npm_config_cache="$scratch/.npm-cache"
cd "$scratch"
npm install --offline --ignore-scripts --no-audit --no-fund ../vendor/hono-4.13.19.tgz
node -p "require('"'hono/package.json').version\"
npm test
node --input-type=module <<'NODE'
import { isDeepStrictEqual } from 'node:util';
import app from './app.mjs';

const cases = [
  { path: '/desk/f2', session: false, status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
  { path: '/desk/f2', session: true, status: 200, body: { id: 'f2', title: 'North' }, steps: 'dispatch,session,read' },
  { path: '/desk/absent-card', session: true, status: 404, body: { error: 'not_found' }, steps: 'dispatch,session,read' },
  { path: '/desk/r9', session: true, status: 502, body: { error: 'invalid_record' }, steps: 'dispatch,session,read,error' },
];

for (const { path, session, ...expected } of cases) {
  const response = await app.request(path, { method: 'GET', headers: session ? { 'x-shift': 'day' } : {} });
  const actual = {
    status: response.status,
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  const contentType = response.headers.get('content-type');
  const pass = isDeepStrictEqual(actual, expected) && contentType?.split(';')[0] === 'application/json';
  console.log(JSON.stringify({ path, session, pass, actual, contentType, ...(pass ? {} : { expected }) }));
  if ("'!pass) process.exitCode = 1;
}
NODE'

